nset = set()
n = int(input())

def reslove(x, y, num, flag):
	if num > n or (flag and num == 0):
		return
	if num > 0:
		nset.add(num)
	reslove(x, y, num * 10 + x, True)
	reslove(x, y, num * 10 + y, True)
for i in range(10):
	for j in range(i + 1, 10):
		reslove(i, j, 0, False)
print(len(nset))
